function makeReturner(n) {
  return function () {
    return n;
  };
}

var callbacks = [];
for (var i = 0; i < 3; i++) {
  callbacks.push(makeReturner(i));
}
console.log(callbacks[0](), callbacks[1](), callbacks[2]());
